import heapq, ipaddress, itertools

# --- longest-prefix match
routes = {"0.0.0.0/0": "isp", "10.0.0.0/8": "core", "10.1.0.0/16": "site-a", "10.1.2.0/24": "lab", "192.0.2.0/24": "dmz"}
table = sorted(((ipaddress.ip_network(p), hop) for p, hop in routes.items()), key=lambda e: -e[0].prefixlen)
def lookup(address):
    address = ipaddress.ip_address(address)
    return next(hop for network, hop in table if address in network)
for address in ("10.1.2.9", "10.1.9.9", "10.9.9.9", "192.0.2.77", "8.8.8.8"):
    brute = max((n for n, _ in table if ipaddress.ip_address(address) in n), key=lambda n: n.prefixlen)
    assert routes[str(brute)] == lookup(address)
    print(f"{address:>11} -> {lookup(address):7} (matched {brute})")

# --- shortest paths (the computation OSPF routers perform on the link-state map)
links = {("A", "B"): 1, ("B", "C"): 1, ("A", "C"): 5, ("C", "D"): 1, ("B", "D"): 4, ("D", "E"): 2, ("C", "E"): 5}
graph = {}
for (u, v), cost in links.items():
    graph.setdefault(u, {})[v] = cost; graph.setdefault(v, {})[u] = cost
def dijkstra(source):
    best, queue = {source: 0}, [(0, source)]
    while queue:
        cost, node = heapq.heappop(queue)
        if cost > best[node]:
            continue
        for neighbour, weight in graph[node].items():
            if cost + weight < best.get(neighbour, 1e9):
                best[neighbour] = cost + weight; heapq.heappush(queue, (cost + weight, neighbour))
    return best
def brute_force(source, target):
    others = [n for n in graph if n not in (source, target)]
    best = 1e9
    for r in range(len(others) + 1):
        for middle in itertools.permutations(others, r):
            path = (source, *middle, target)
            if all(b in graph[a] for a, b in zip(path, path[1:])):
                best = min(best, sum(graph[a][b] for a, b in zip(path, path[1:])))
    return best
distances = dijkstra("A")
print("cost from A:", dict(sorted(distances.items())), "| agrees with exhaustive search:", all(distances[t] == brute_force("A", t) for t in "BCDE"))

# --- BGP best-path selection in the order of RFC 4271, section 9.1
routes_bgp = [
    {"name": "via AS100", "local_pref": 100, "as_path": [100, 400], "origin": 0, "med": 10, "neighbour_as": 100},
    {"name": "via AS200", "local_pref": 100, "as_path": [200, 300, 400], "origin": 0, "med": 5, "neighbour_as": 200},
    {"name": "via AS500", "local_pref": 200, "as_path": [500, 600, 700, 400], "origin": 2, "med": 0, "neighbour_as": 500},
    {"name": "via AS100 (second link)", "local_pref": 100, "as_path": [100, 400], "origin": 0, "med": 3, "neighbour_as": 100},
]
def best_path(candidates):
    steps = []
    top = max(r["local_pref"] for r in candidates)
    candidates = [r for r in candidates if r["local_pref"] == top]; steps.append(("highest local preference", [r["name"] for r in candidates]))
    shortest = min(len(r["as_path"]) for r in candidates)
    candidates = [r for r in candidates if len(r["as_path"]) == shortest]; steps.append(("shortest AS_PATH", [r["name"] for r in candidates]))
    lowest = min(r["origin"] for r in candidates)
    candidates = [r for r in candidates if r["origin"] == lowest]; steps.append(("lowest origin", [r["name"] for r in candidates]))
    candidates = [r for r in candidates if not any(o["neighbour_as"] == r["neighbour_as"] and o["med"] < r["med"] for o in candidates)]
    steps.append(("lowest MED (same neighbouring AS only)", [r["name"] for r in candidates]))
    return candidates[0]["name"], steps
chosen, steps = best_path(routes_bgp)
for criterion, left in steps:
    print(f"  after {criterion}: {left}")
print("BGP selects:", chosen)
print("without the local-preference policy the shortest path would win:", best_path([dict(r, local_pref=100) for r in routes_bgp])[0])

# --- a learning switch
class Switch:
    def __init__(self, ports): self.ports, self.mac_table = ports, {}
    def frame(self, in_port, src, dst):
        self.mac_table[src] = in_port                                 # learn
        if dst in self.mac_table and dst != "ff:ff":
            return [self.mac_table[dst]]
        return [p for p in range(self.ports) if p != in_port]         # flood unknown or broadcast
sw = Switch(4)
print("A->B (B unknown):", sw.frame(0, "A", "B"), "| B->A (A learned):", sw.frame(1, "B", "A"), "| A->B (now learned):", sw.frame(0, "A", "B"), "| broadcast from C:", sw.frame(2, "C", "ff:ff"))

