from dataclasses import dataclass

@dataclass(frozen=True)
class Request:
    user: str; role: str; mfa: bool; device_managed: bool; device_patched: bool; network: str; resource: str; hour: int

RESOURCES = {"wiki": {"sensitivity": 1}, "payroll": {"sensitivity": 3}, "prod-db": {"sensitivity": 4}}
ROLE_ACCESS = {"employee": {"wiki"}, "hr": {"wiki", "payroll"}, "dba": {"wiki", "prod-db"}}                 # least privilege: what each role may ever touch

def perimeter_decision(r):
    return "allow" if r.network == "internal" else "deny"                                                  # the old model: location is trust

def zero_trust_decision(r):
    reasons = []
    if r.resource not in ROLE_ACCESS.get(r.role, set()):
        return "deny", ["role is not entitled to this resource"]                                         # deny by default
    sensitivity = RESOURCES[r.resource]["sensitivity"]
    if not r.mfa:
        reasons.append("strong authentication required")
    if sensitivity >= 2 and not (r.device_managed and r.device_patched):
        reasons.append("device must be managed and patched for sensitive data")
    if sensitivity >= 4 and not (7 <= r.hour <= 19):
        reasons.append("production data only in business hours")
    if r.network == "unknown-country" and sensitivity >= 3:
        reasons.append("high-risk location for sensitive data")
    return ("allow", ["all conditions met"]) if not reasons else ("deny", reasons)

cases = [
    Request("ana", "employee", True, True, True, "internal", "wiki", 10),
    Request("ben", "employee", True, True, True, "internal", "payroll", 10),               # inside the network but not entitled
    Request("cho", "hr", True, True, True, "home", "payroll", 14),                          # outside the network, fully compliant
    Request("dev", "hr", True, False, False, "internal", "payroll", 14),                    # inside the network, unmanaged device
    Request("eva", "dba", True, True, True, "internal", "prod-db", 3),                      # inside, entitled, wrong time
    Request("fay", "hr", True, True, True, "unknown-country", "payroll", 14),
]
print(f"{'user':5} {'resource':8} {'network':16} {'perimeter':10} {'zero trust':10} reasons")
for r in cases:
    decision, reasons = zero_trust_decision(r)
    print(f"{r.user:5} {r.resource:8} {r.network:16} {perimeter_decision(r):10} {decision:10} {'; '.join(reasons)}")
wrongly_allowed = [r.user for r in cases if perimeter_decision(r) == "allow" and zero_trust_decision(r)[0] == "deny"]
wrongly_denied = [r.user for r in cases if perimeter_decision(r) == "deny" and zero_trust_decision(r)[0] == "allow"]
print("the perimeter model allows requests that zero trust denies:", wrongly_allowed, "| and denies one that zero trust allows:", wrongly_denied)

session = Request("cho", "hr", True, True, True, "home", "payroll", 14)
print("session start:", zero_trust_decision(session)[0])
drifted = Request(**{**session.__dict__, "device_patched": False})
print("an hour later the device falls out of patch compliance:", zero_trust_decision(drifted)[0], "-", zero_trust_decision(drifted)[1][0])

import base64, hashlib, hmac, json, struct, time

def hotp(secret, counter, digits=8, algorithm=hashlib.sha1):
    digest = hmac.new(secret, struct.pack(">Q", counter), algorithm).digest()
    offset = digest[-1] & 0x0F
    value = (struct.unpack(">I", digest[offset:offset + 4])[0] & 0x7FFFFFFF) % 10 ** digits
    return str(value).zfill(digits)
def totp(secret, when, step=30, digits=8, algorithm=hashlib.sha1):
    return hotp(secret, int(when // step), digits, algorithm)

vectors = [(59, "94287082", "46119246", "90693936"), (1111111109, "07081804", "68084774", "25091201"), (1234567890, "89005924", "91819424", "93441116"), (2000000000, "69279037", "90698825", "38618901")]
sha1_key = b"12345678901234567890"; sha256_key = b"12345678901234567890123456789012"; sha512_key = b"1234567890123456789012345678901234567890123456789012345678901234"
