ROLE_PERMISSIONS = {"clerk": {"invoice:create", "invoice:read"}, "approver": {"invoice:read", "invoice:approve"}, "auditor": {"invoice:read", "audit:read"}}
def rbac(roles, permission): return any(permission in ROLE_PERMISSIONS[r] for r in roles)
def abac(user, action, resource, context):
    if action == "invoice:approve":
        return user["id"] != resource["created_by"] and resource["amount"] <= user.get("limit", 0) and context["mfa"]       # separation of duties, limit, strong auth
    return rbac(user["roles"], action)
ana = {"id": "ana", "roles": ["clerk", "approver"], "limit": 10000}
invoice = {"created_by": "ana", "amount": 500}
print("RBAC alone lets Ana create and approve her own invoice:", rbac(ana["roles"], "invoice:create") and rbac(ana["roles"], "invoice:approve"))
print("ABAC with separation of duties blocks her approving it:", not abac(ana, "invoice:approve", invoice, {"mfa": True}))
print("another approver within the limit and with MFA may approve:", abac({"id": "bo", "roles": ["approver"], "limit": 10000}, "invoice:approve", invoice, {"mfa": True}))
print("without MFA the same approver may not:", not abac({"id": "bo", "roles": ["approver"], "limit": 10000}, "invoice:approve", invoice, {"mfa": False}))

def b64(data): return base64.urlsafe_b64encode(data).rstrip(b"=").decode()
def unb64(text): return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))
SECRET = b"server-side-secret"
def make(claims, alg="HS256", secret=SECRET):
    head, body = b64(json.dumps({"alg": alg, "typ": "JWT"}).encode()), b64(json.dumps(claims).encode())
    signature = b64(hmac.new(secret, f"{head}.{body}".encode(), hashlib.sha256).digest()) if alg == "HS256" else ""
    return f"{head}.{body}.{signature}"
def naive_verify(token):                                           # VULNERABLE: trusts the algorithm named in the token
    head, body, signature = token.split(".")
    alg = json.loads(unb64(head))["alg"]
    if alg == "none":
        return json.loads(unb64(body))
    expected = b64(hmac.new(SECRET, f"{head}.{body}".encode(), hashlib.sha256).digest())
    return json.loads(unb64(body)) if hmac.compare_digest(signature, expected) else None
def correct_verify(token, now=1_800_000_000, audience="invoice-api"):
    head, body, signature = token.split(".")
    if json.loads(unb64(head))["alg"] != "HS256":                    # the verifier decides the algorithm, never the token
        return None
    expected = b64(hmac.new(SECRET, f"{head}.{body}".encode(), hashlib.sha256).digest())
    claims = json.loads(unb64(body))
    if not hmac.compare_digest(signature, expected) or claims.get("exp", 0) < now or claims.get("aud") != audience:
        return None
    return claims
legit = make({"sub": "ana", "role": "clerk", "aud": "invoice-api", "exp": 1_900_000_000})
forged = make({"sub": "attacker", "role": "admin", "aud": "invoice-api", "exp": 1_900_000_000}, alg="none")
expired = make({"sub": "ana", "aud": "invoice-api", "exp": 1_000})
wrong_audience = make({"sub": "ana", "aud": "other-api", "exp": 1_900_000_000})
print("SIMULATION: naive verifier accepts the forged 'none' token as admin:", (naive_verify(forged) or {}).get("role") == "admin")
print("correct verifier: legitimate token", correct_verify(legit) is not None, "| forged none", correct_verify(forged) is None, "| expired", correct_verify(expired) is None, "| wrong audience", correct_verify(wrong_audience) is None)

from collections import deque

ZONES = ["internet", "dmz", "app", "db", "admin", "logging"]
# (source, destination, port, action); evaluated top to bottom, first match wins; the last rule is the explicit default deny
BASE = [
    ("internet", "dmz", 443, "allow"),
    ("dmz", "app", 8443, "allow"),
    ("app", "db", 5432, "allow"),
    ("admin", "app", 22, "allow"),
    ("admin", "db", 22, "allow"),
    ("dmz", "logging", 514, "allow"), ("app", "logging", 514, "allow"), ("db", "logging", 514, "allow"), ("admin", "logging", 514, "allow"),
    ("any", "any", None, "deny"),
]
def decide(rules, src, dst, port):
    for r_src, r_dst, r_port, action in rules:
        if r_src in ("any", src) and r_dst in ("any", dst) and r_port in (None, port):
            return action
    return "deny"

def reachable_from(rules, start, ports=(22, 443, 514, 5432, 8443)):
    edges = {z: {d for d in ZONES if d != z and any(decide(rules, z, d, p) == "allow" for p in ports)} for z in ZONES}
    seen, queue = {start}, deque([start])
    while queue:
        for nxt in edges[queue.popleft()]:
            if nxt not in seen:
                seen.add(nxt); queue.append(nxt)
    return seen - {start}, edges

def shadowed(rules):
    found = []
    for i, (s, d, p, a) in enumerate(rules):
        for earlier in rules[:i]:
            if earlier[0] in ("any", s) and earlier[1] in ("any", d) and earlier[2] in (None, p) and earlier[3] != "-":
                if (earlier[0] == "any" or earlier[0] == s) and (earlier[1] == "any" or earlier[1] == d) and (earlier[2] is None or earlier[2] == p):
                    found.append((i, earlier)); break
    return found

def audit(name, rules):
    from_internet, edges = reachable_from(rules, "internet")
    print(f"--- {name}")
    print("directly allowed from the internet:", sorted(edges["internet"]))
    print("reachable from the internet through any chain of allowed hops:", sorted(from_internet))
    print("internet can reach the database directly:", "db" in edges["internet"], "| through a chain (lateral movement):", "db" in from_internet)
    print("every zone can send logs:", all("logging" in edges[z] for z in ZONES if z not in ("internet", "logging")))
    print("shadowed (unreachable) rules:", shadowed(rules) or "none")

audit("base policy", BASE)
broad = BASE[:1] + [("dmz", "any", None, "allow")] + BASE[1:]                   # a convenient rule: the DMZ may talk to everything
audit("after adding 'dmz -> any: allow'", broad)
print("with the broad rule the internet-facing DMZ can open the database directly:", decide(broad, "dmz", "db", 5432))
print("in the base policy the same connection is:", decide(BASE, "dmz", "db", 5432))
